    if (!f.opened) return;
    CHECK_EQ(f.pdfPages, 1, "pageCount");
    CHECK(f.res.ok, "import ok", f.res.error.toStdString());
    CHECK_EQ(f.res.pathsImported, 5, "pathsImported");
    CHECK_EQ(f.res.textsImported, 1, "textsImported");
    CHECK_EQ(f.res.imagesImported, 0, "imagesImported");
